CREATE TABLE IF NOT EXISTS customers (customer_id VARCHAR(20) PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, phone VARCHAR(20) NOT NULL, password_hash VARCHAR(128) NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS admins (admin_id VARCHAR(30) PRIMARY KEY, password_hash VARCHAR(128) NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS accounts (account_id VARCHAR(20) PRIMARY KEY, customer_id VARCHAR(20) NOT NULL, account_type VARCHAR(20) NOT NULL, balance DECIMAL(19,2) NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMP NOT NULL, CONSTRAINT fk_account_customer FOREIGN KEY(customer_id) REFERENCES customers(customer_id));
CREATE TABLE IF NOT EXISTS transactions (transaction_id VARCHAR(30) PRIMARY KEY, source_account_id VARCHAR(20), destination_account_id VARCHAR(20), transaction_type VARCHAR(20) NOT NULL, amount DECIMAL(19,2) NOT NULL, timestamp TIMESTAMP NOT NULL, status VARCHAR(20) NOT NULL, risk_score INT NOT NULL, risk_level VARCHAR(20) NOT NULL, description VARCHAR(500));
CREATE TABLE IF NOT EXISTS fraud_alerts (alert_id VARCHAR(30) PRIMARY KEY, transaction_id VARCHAR(30) NOT NULL, rule_triggered VARCHAR(500) NOT NULL, risk_score INT NOT NULL, risk_level VARCHAR(20) NOT NULL, review_status VARCHAR(30) NOT NULL, created_at TIMESTAMP NOT NULL, reviewed_at TIMESTAMP, CONSTRAINT fk_alert_transaction FOREIGN KEY(transaction_id) REFERENCES transactions(transaction_id));
